  1	use super::{
  2	    AUTOMATIC_THRESHOLD, AddressMatchQuality, BTreeMap, BTreeSet, EntityIngestionError,
  3	    FunderObservationId, FunderRole, IdentityBasis, Observation, ObservationResolution,
  4	    PairDecision, PairDisposition, PairReason, ResolutionInput, ScoredPair, ScoringInput, invalid,
  5	};
  6	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
  7	enum EntityKind {
  8	    Person,
  9	    Organisation,
 10	    Unknown,
 11	}
 12	fn kind(observation: &Observation) -> EntityKind {
 13	    match observation
 14	        .donor_kind
 15	        .as_deref()
 16	        .map(str::trim)
 17	        .map(str::to_ascii_lowercase)
 18	        .as_deref()
 19	    {
 20	        Some("individual" | "person") => EntityKind::Person,
 21	        Some(
 22	            "company"
 23	            | "charity"
 24	            | "trade union"
 25	            | "union"
 26	            | "other organisation"
 27	            | "organisation"
 28	            | "unincorporated association"
 29	            | "registered party"
 30	            | "trust"
 31	            | "limited liability partnership"
 32	            | "friendly society"
 33	            | "building society",
 34	        ) => EntityKind::Organisation,
 35	        _ => EntityKind::Unknown,
 36	    }
 37	}
 38	pub(super) fn company(observation: &Observation) -> Option<String> {
 39	    if observation
 40	        .donor_kind
 41	        .as_deref()
 42	        .is_some_and(|kind| !kind.trim().eq_ignore_ascii_case("company"))
 43	    {
 44	        return None;
 45	    }
 46	    let number = observation
 47	        .donor_company_number
 48	        .as_ref()?
 49	        .trim_matches(|c: char| c.is_ascii_whitespace())
 50	        .to_ascii_uppercase();
 51	    (number.len() == 8
 52	        && number.bytes().all(|b| b.is_ascii_alphanumeric())
 53	        && number.bytes().any(|b| b.is_ascii_digit()))
 54	    .then_some(number)
 55	}
 56	
 57	#[derive(Clone, Copy)]
 58	enum LinkEvidence {
 59	    Statistical,
 60	    DonorName,
 61	    ExtractedName,
 62	    TradeUnionFamily,
 63	}
 64	#[derive(Clone, Copy)]
 65	enum EdgeEligibility {
 66	    Link(LinkEvidence),
 67	    Review,
 68	    Reject(PairReason),
